const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function advToast(msg, type) { try { (window.showToast || function () {})(msg, type || 'info'); } catch (_) {} }

// Proxy endpoint, resolved at call time (same contract as webai.js / threatforest.js).
// The server proxy holds the provider key; nothing sensitive ships to the browser.
function proxyUrl() { try { if (window.DARKNODE_PROXY_URL) return window.DARKNODE_PROXY_URL; } catch (_) {} return '/api/chat'; }

// ============================================================================
// PROMPT BUILDER — turns the structured infrastructure form + free-text
// scenario into a single analyst request for the model. No canned rules.
// ============================================================================
function buildPrompt(config) {
  var lines = [];
  lines.push('Organization profile:');
  lines.push('- Industry: ' + (config.industry || 'unspecified'));
  lines.push('- Internal architecture: ' + (config.architecture || 'unspecified'));
  lines.push('- Approximate employee count: ' + (config.employees || 'unspecified'));
  lines.push('- Security awareness level: ' + (config.awareness || 'unspecified'));
  lines.push('- Security budget tier: ' + (config.budget || 'unspecified'));
  lines.push('- External-facing services: ' + (config.services.length ? config.services.join(', ') : 'none specified'));
  lines.push('- Security controls currently deployed: ' + (config.controls.length ? config.controls.join(', ') : 'none specified'));
  if (config.weaknesses && config.weaknesses.trim()) {
    lines.push('- Known weaknesses / free-text context from the defender:');
    lines.push(config.weaknesses.trim());
  }
  lines.push('');
  lines.push('Act as an adversary-emulation analyst helping this defender. Produce a defensive-planning assessment with these sections, using Markdown headings (##):');
  lines.push('1. Top Attack Scenarios — the 3 most likely initial-access/attack paths for THIS specific profile, each with a rough likelihood, the relevant MITRE ATT&CK technique ID(s), and why it applies here.');
  lines.push('2. Kill Chain — for the single most likely scenario, a step-by-step chain (phase, action, MITRE ID, how a defender would detect it).');
  lines.push('3. Blind Spots — attack phases where the listed controls give little or no coverage.');
  lines.push('4. Prioritized Remediation — concrete, ordered actions (priority, action, expected impact, rough effort).');
  lines.push('5. Executive Summary — 3-5 sentences a non-technical leader can act on.');
  lines.push('');
  lines.push('Be specific to the inputs above. Do not invent exact dollar figures or precise percentages as if measured; if you estimate, say it is an estimate. Keep it concrete and terse.');
  return lines.join('\n');
}

var ADV_SYS = 'You are a senior adversary-emulation and blue-team planning analyst for a defensive security platform. You help defenders understand how an attacker would approach their own environment so they can prioritize defenses. Assume the user is assessing an organization they are authorized to defend. Give real MITRE ATT&CK technique IDs, real detection guidance, and prioritized, actionable remediation. Be concrete and avoid boilerplate disclaimers.';

// ============================================================================
// Minimal, safe Markdown -> HTML (escape first, then apply a few patterns).
// ============================================================================
function mdToHtml(md) {
  var safe = esc(md);
  var out = [];
  var inList = false;
  safe.split('\n').forEach(function (raw) {
    var line = raw;
    var bullet = line.match(/^\s*[-*]\s+(.*)$/);
    if (bullet) {
      if (!inList) { out.push('<ul style="margin:6px 0 10px;padding-left:20px">'); inList = true; }
      out.push('<li style="margin-bottom:4px">' + inline(bullet[1]) + '</li>');
      return;
    }
    if (inList) { out.push('</ul>'); inList = false; }
    var h = line.match(/^(#{1,4})\s+(.*)$/);
    if (h) {
      var lvl = h[1].length;
      var size = lvl <= 2 ? '1rem' : '.88rem';
      out.push('<h3 style="font-size:' + size + ';margin:16px 0 6px;color:var(--acc)">' + inline(h[2]) + '</h3>');
      return;
    }
    if (line.trim() === '') { out.push('<div style="height:6px"></div>'); return; }
    out.push('<div style="margin-bottom:4px;line-height:1.6">' + inline(line) + '</div>');
  });
  if (inList) out.push('</ul>');
  return out.join('');
  function inline(t) {
    return t
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/`([^`]+)`/g, '<code>$1</code>');
  }
}

// ============================================================================
// RENDER FUNCTION
// ============================================================================
export function renderAdversaryAI(main) {
  var activeTab = 'input';
  var analysisText = '';
  var analysisError = '';
  var analysisBusy = false;
  var abortCtl = null;
  var config = {
    services: [],
    architecture: 'ad',
    controls: [],
    awareness: 'medium',
    industry: 'tech',
    budget: 'medium',
    employees: 200,
    weaknesses: '',
  };

  function render() {
    main.innerHTML =
      '<style>' +
      '.adv-wrap { font-family: inherit; }' +
      '.adv-header { display:flex; align-items:center; gap:16px; padding:16px 0; border-bottom:2px solid var(--acc); }' +
      '.adv-title { font-size:1.5rem; font-weight:800; color:var(--acc); margin:0; letter-spacing:.05em; }' +
      '.adv-tabs { display:flex; gap:2px; overflow-x:auto; padding:12px 0 0; }' +
      '.adv-tab { background:transparent; border:none; border-bottom:2px solid transparent; color:var(--mut); padding:10px 16px; font-size:.75rem; font-weight:600; letter-spacing:.04em; text-transform:uppercase; cursor:pointer; white-space:nowrap; font-family:inherit; }' +
      '.adv-tab:hover { color:var(--txt); }' +
      '.adv-tab.active { color:var(--acc); border-bottom-color:var(--acc); }' +
      '.adv-form-group { margin-bottom:16px; }' +
      '.adv-label { display:block; font-size:.78rem; font-weight:600; color:var(--txt); margin-bottom:6px; }' +
      '.adv-sublabel { font-size:.72rem; color:var(--mut); font-weight:400; }' +
      '.adv-select { background:var(--card); color:var(--txt); border:1px solid var(--line); padding:8px 12px; border-radius:4px; font-size:.8rem; width:100%; max-width:400px; font-family:inherit; }' +
      '.adv-select:focus { border-color:var(--acc); outline:none; }' +
      '.adv-checks { display:flex; flex-wrap:wrap; gap:8px; }' +
      '.adv-check { display:flex; align-items:center; gap:6px; font-size:.78rem; cursor:pointer; padding:6px 12px; border:1px solid var(--line); border-radius:4px; transition:all .15s; }' +
      '.adv-check:hover { border-color:var(--acc); }' +
      '.adv-check.on { border-color:var(--acc); background:rgba(0,229,255,0.08); color:var(--acc); }' +
      '.adv-btn { background:var(--acc); color:var(--bg); border:none; padding:12px 28px; font-size:.85rem; font-weight:700; border-radius:4px; cursor:pointer; letter-spacing:.04em; text-transform:uppercase; font-family:inherit; }' +
      '.adv-btn:hover { filter:brightness(1.1); }' +
      '.adv-btn:disabled { opacity:.5; cursor:default; }' +
      '.adv-analysis { background:var(--card); border:1px solid var(--line); border-radius:6px; padding:18px 22px; font-size:.84rem; color:var(--txt); max-width:900px; }' +
      '.adv-analysis code { background:var(--bg); padding:1px 5px; border-radius:3px; font-size:.82em; }' +
      '</style>' +
      '<div class="adv-wrap">' +
        '<div class="adv-header">' +
          '<h1 class="adv-title">ADVERSARY MIND</h1>' +
          '<span style="color:var(--mut);font-size:.75rem">AI Attack Prediction &amp; Defense Planning</span>' +
        '</div>' +
        '<div class="adv-tabs">' +
          '<button class="adv-tab' + (activeTab === 'input' ? ' active' : '') + '" data-tab="input">Infrastructure</button>' +
          '<button class="adv-tab' + (activeTab === 'analysis' ? ' active' : '') + '" data-tab="analysis">Analysis</button>' +
        '</div>' +
        '<div id="adv-content" style="padding:16px 0"></div>' +
      '</div>';

    main.querySelector('.adv-tabs').onclick = function (e) {
      var b = e.target.closest('.adv-tab');
      if (!b) return;
      activeTab = b.dataset.tab;
      render();
    };

    var content = main.querySelector('#adv-content');
    if (activeTab === 'input') renderInputTab(content);
    else if (activeTab === 'analysis') renderAnalysisTab(content);
  }

  function renderInputTab(container) {
    var services = [
      { id: 'web_app', label: 'Web Application' }, { id: 'vpn', label: 'VPN' },
      { id: 'email', label: 'Email (Exchange/O365)' }, { id: 'api', label: 'API Endpoints' },
      { id: 'rdp', label: 'RDP (Internet-Facing)' }, { id: 'ssh', label: 'SSH (Internet-Facing)' },
      { id: 'cloud_console', label: 'Cloud Console (AWS/Azure/GCP)' }, { id: 'ftp', label: 'FTP' },
      { id: 'dns', label: 'DNS Server' }, { id: 'database', label: 'Database (External)' },
    ];
    var controls = [
      { id: 'edr', label: 'EDR' }, { id: 'siem', label: 'SIEM' }, { id: 'mfa', label: 'MFA' },
      { id: 'waf', label: 'WAF' }, { id: 'segmentation', label: 'Network Segmentation' },
      { id: 'dlp', label: 'DLP' }, { id: 'ids', label: 'IDS/IPS' }, { id: 'email_security', label: 'Email Security' },
      { id: 'vuln_management', label: 'Vuln Management' }, { id: 'backup', label: 'Offline Backups' },
      { id: 'pam', label: 'PAM' }, { id: 'zt', label: 'Zero Trust' },
    ];

    container.innerHTML =
      '<h2 style="font-size:1rem;margin:0 0 16px">Describe Your Infrastructure</h2>' +
      '<p class="muted" style="font-size:.82rem;margin:-12px 0 20px">The more accurate your inputs, the more precise the analysis. Your description is sent to the Darknode AI model to generate the assessment.</p>' +

      '<div class="adv-form-group">' +
        '<label class="adv-label">Industry</label>' +
        '<select class="adv-select" id="adv-industry">' +
          '<option value="healthcare"' + (config.industry === 'healthcare' ? ' selected' : '') + '>Healthcare</option>' +
          '<option value="finance"' + (config.industry === 'finance' ? ' selected' : '') + '>Finance / Banking</option>' +
          '<option value="tech"' + (config.industry === 'tech' ? ' selected' : '') + '>Technology</option>' +
          '<option value="government"' + (config.industry === 'government' ? ' selected' : '') + '>Government</option>' +
          '<option value="education"' + (config.industry === 'education' ? ' selected' : '') + '>Education</option>' +
          '<option value="retail"' + (config.industry === 'retail' ? ' selected' : '') + '>Retail</option>' +
          '<option value="energy"' + (config.industry === 'energy' ? ' selected' : '') + '>Energy / Utilities</option>' +
          '<option value="manufacturing"' + (config.industry === 'manufacturing' ? ' selected' : '') + '>Manufacturing</option>' +
        '</select>' +
      '</div>' +

      '<div class="adv-form-group">' +
        '<label class="adv-label">External-Facing Services <span class="adv-sublabel">(select all that apply)</span></label>' +
        '<div class="adv-checks" id="adv-services">' +
          services.map(function (s) {
            return '<label class="adv-check' + (config.services.indexOf(s.id) !== -1 ? ' on' : '') + '" data-id="' + s.id + '">' +
              '<input type="checkbox"' + (config.services.indexOf(s.id) !== -1 ? ' checked' : '') + ' style="accent-color:var(--acc)"> ' + esc(s.label) + '</label>';
          }).join('') +
        '</div>' +
      '</div>' +

      '<div class="adv-form-group">' +
        '<label class="adv-label">Internal Architecture</label>' +
        '<select class="adv-select" id="adv-arch">' +
          '<option value="ad"' + (config.architecture === 'ad' ? ' selected' : '') + '>Active Directory (On-Premises)</option>' +
          '<option value="cloud"' + (config.architecture === 'cloud' ? ' selected' : '') + '>Cloud-Native (AWS/Azure/GCP)</option>' +
          '<option value="hybrid"' + (config.architecture === 'hybrid' ? ' selected' : '') + '>Hybrid (AD + Cloud)</option>' +
          '<option value="flat"' + (config.architecture === 'flat' ? ' selected' : '') + '>Flat Network (No Segmentation)</option>' +
          '<option value="segmented"' + (config.architecture === 'segmented' ? ' selected' : '') + '>Segmented Network</option>' +
        '</select>' +
      '</div>' +

      '<div class="adv-form-group">' +
        '<label class="adv-label">Security Controls Deployed <span class="adv-sublabel">(select all that apply)</span></label>' +
        '<div class="adv-checks" id="adv-controls">' +
          controls.map(function (c) {
            return '<label class="adv-check' + (config.controls.indexOf(c.id) !== -1 ? ' on' : '') + '" data-id="' + c.id + '">' +
              '<input type="checkbox"' + (config.controls.indexOf(c.id) !== -1 ? ' checked' : '') + ' style="accent-color:var(--acc)"> ' + esc(c.label) + '</label>';
          }).join('') +
        '</div>' +
      '</div>' +

      '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px">' +
        '<div class="adv-form-group">' +
          '<label class="adv-label">Employee Count</label>' +
          '<input type="number" class="adv-select" id="adv-employees" value="' + config.employees + '" min="1" max="100000">' +
        '</div>' +
        '<div class="adv-form-group">' +
          '<label class="adv-label">Security Awareness</label>' +
          '<select class="adv-select" id="adv-awareness">' +
            '<option value="low"' + (config.awareness === 'low' ? ' selected' : '') + '>Low (no training)</option>' +
            '<option value="medium"' + (config.awareness === 'medium' ? ' selected' : '') + '>Medium (annual training)</option>' +
            '<option value="high"' + (config.awareness === 'high' ? ' selected' : '') + '>High (regular phishing simulations)</option>' +
          '</select>' +
        '</div>' +
        '<div class="adv-form-group">' +
          '<label class="adv-label">Budget Tier</label>' +
          '<select class="adv-select" id="adv-budget">' +
            '<option value="startup"' + (config.budget === 'startup' ? ' selected' : '') + '>Startup (minimal security budget)</option>' +
            '<option value="small"' + (config.budget === 'small' ? ' selected' : '') + '>Small ($50-200K/yr)</option>' +
            '<option value="medium"' + (config.budget === 'medium' ? ' selected' : '') + '>Medium ($200K-1M/yr)</option>' +
            '<option value="enterprise"' + (config.budget === 'enterprise' ? ' selected' : '') + '>Enterprise ($1M+/yr)</option>' +
          '</select>' +
        '</div>' +
      '</div>' +

      '<div class="adv-form-group">' +
        '<label class="adv-label">Known Weaknesses / Scenario <span class="adv-sublabel">(optional — anything you already know, or a specific scenario to analyze)</span></label>' +
        '<textarea class="adv-select" id="adv-weaknesses" rows="3" style="resize:vertical;max-width:100%">' + esc(config.weaknesses) + '</textarea>' +
      '</div>' +

      '<button class="adv-btn" id="adv-predict">Analyze with Darknode AI</button>';

    // Wire service checkboxes
    container.querySelector('#adv-services').addEventListener('change', function (e) {
      var cb = e.target;
      if (cb.type !== 'checkbox') return;
      var label = cb.closest('.adv-check');
      var id = label.dataset.id;
      if (cb.checked) { if (config.services.indexOf(id) === -1) config.services.push(id); label.classList.add('on'); }
      else { config.services = config.services.filter(function (s) { return s !== id; }); label.classList.remove('on'); }
    });

    // Wire control checkboxes
    container.querySelector('#adv-controls').addEventListener('change', function (e) {
      var cb = e.target;
      if (cb.type !== 'checkbox') return;
      var label = cb.closest('.adv-check');
      var id = label.dataset.id;
      if (cb.checked) { if (config.controls.indexOf(id) === -1) config.controls.push(id); label.classList.add('on'); }
      else { config.controls = config.controls.filter(function (c) { return c !== id; }); label.classList.remove('on'); }
    });

    // Wire analyze button
    container.querySelector('#adv-predict').onclick = function () {
      config.industry = container.querySelector('#adv-industry').value;
      config.architecture = container.querySelector('#adv-arch').value;
      config.employees = parseInt(container.querySelector('#adv-employees').value) || 200;
      config.awareness = container.querySelector('#adv-awareness').value;
      config.budget = container.querySelector('#adv-budget').value;
      config.weaknesses = container.querySelector('#adv-weaknesses').value;
      activeTab = 'analysis';
      render();
      runAnalysis();
    };
  }

  function renderAnalysisTab(container) {
    if (!analysisText && !analysisBusy && !analysisError) {
      container.innerHTML = '<p class="muted" style="padding:40px;text-align:center">Describe your infrastructure first, then click "Analyze with Darknode AI".</p>';
      return;
    }

    var header =
      '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap">' +
        '<h2 style="font-size:1rem;margin:0;flex:1">Attack &amp; Defense Analysis</h2>' +
        (analysisBusy
          ? '<span class="muted" style="font-size:.78rem">Generating…</span>'
          : '<button class="btn sm" id="adv-rerun">Re-run</button>' +
            (analysisText ? '<button class="btn sm" id="adv-copy">Copy</button>' : '')) +
      '</div>';

    var body;
    if (analysisError) {
      body = '<div class="adv-analysis" style="border-color:#ff1744;color:#ff8a9a">' + esc(analysisError) + '</div>';
    } else {
      body = '<div class="adv-analysis" id="adv-analysis-body">' +
        (analysisText ? mdToHtml(analysisText) : '<span class="muted">Contacting the Darknode AI model…</span>') +
      '</div>';
    }

    container.innerHTML = header + body;

    var rerun = container.querySelector('#adv-rerun');
    if (rerun) rerun.onclick = function () { runAnalysis(); };
    var copy = container.querySelector('#adv-copy');
    if (copy) copy.onclick = function () {
      navigator.clipboard.writeText(analysisText).then(function () {
        copy.textContent = 'Copied!';
        setTimeout(function () { copy.textContent = 'Copy'; }, 1500);
      }).catch(function () { advToast('Copy failed', 'error'); });
    };
  }

  async function runAnalysis() {
    if (analysisBusy && abortCtl) { try { abortCtl.abort(); } catch (_) {} }
    analysisText = '';
    analysisError = '';
    analysisBusy = true;
    if (activeTab === 'analysis') renderAnalysisTab(main.querySelector('#adv-content'));

    abortCtl = new AbortController();
    var prompt = buildPrompt(config);

    try {
      var r = await fetch(proxyUrl(), {
        method: 'POST',
        signal: abortCtl.signal,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          provider: 'gemini',
          model: 'gemini-flash-latest',
          messages: [{ role: 'system', content: ADV_SYS }, { role: 'user', content: prompt }],
        }),
      });
      if (!r.ok || !r.body) throw new Error('AI backend returned HTTP ' + r.status);

      var reader = r.body.getReader();
      var dec = new TextDecoder();
      var buf = '';
      for (;;) {
        var chunk = await reader.read();
        if (chunk.done) break;
        buf += dec.decode(chunk.value, { stream: true });
        var nl;
        while ((nl = buf.indexOf('\n')) >= 0) {
          var line = buf.slice(0, nl).trim();
          buf = buf.slice(nl + 1);
          if (line.indexOf('data: ') !== 0) continue;
          var payload = line.slice(6);
          if (payload === '[DONE]') break;
          try {
            var j = JSON.parse(payload);
            var d = j.choices && j.choices[0] && j.choices[0].delta;
            if (d && d.content) {
              analysisText += d.content;
              var bodyEl = main.querySelector('#adv-analysis-body');
              if (bodyEl) bodyEl.innerHTML = mdToHtml(analysisText);
            }
          } catch (_) {}
        }
      }

      if (!analysisText) throw new Error('The AI backend returned no content.');
    } catch (e) {
      if (e && e.name === 'AbortError') { analysisBusy = false; return; }
      analysisError = 'Analysis unavailable: ' + ((e && e.message) ? e.message : 'the AI backend is unreachable') +
        '. Check your connection or try again — no analysis is shown rather than fabricated results.';
      advToast('Adversary Mind: AI backend unreachable', 'error');
    } finally {
      if (!(abortCtl && abortCtl.signal && abortCtl.signal.aborted)) analysisBusy = false;
      if (activeTab === 'analysis') renderAnalysisTab(main.querySelector('#adv-content'));
    }
  }

  render();
}
